// TeamsContextMenu (#2385) — a right-click context menu anchored at a cursor position: a full-screen
// dismiss backdrop plus a single danger action row, closes on Escape/backdrop click. Promoted from
// harvested (it was already complete and tested) into base-studio-code, refactored to use the real
// Box/Text primitives instead of local raw-div redeclarations.
import { useEffect, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

export function TeamsContextMenu({
  x = 80, y = 40, deleteLabel = "Delete position", onDelete = () => {}, onClose = () => {},
}: {
  x?: number;
  y?: number;
  /** "Delete position" / "Delete relationship" - set by the caller from the target kind. */
  deleteLabel?: string;
  onDelete?: () => void;
  onClose?: () => void;
}) {
  const [hover, setHover] = useState(false);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  return (
    <>
      <Box
        onClick={onClose}
        onContextMenu={(e: any) => { e.preventDefault(); onClose(); }}
        style={{ position: "fixed", inset: 0, zIndex: 60 }}
      />
      <Box
        role="menu"
        style={{
          position: "fixed", left: x, top: y, zIndex: 61, minWidth: 172,
          background: "var(--bg-elev)", border: "1px solid var(--border)", borderRadius: 8,
          boxShadow: "var(--shadow-md)", padding: 4,
        }}
      >
        <Box
          role="menuitem"
          onClick={() => { onDelete(); onClose(); }}
          onMouseEnter={() => setHover(true)}
          onMouseLeave={() => setHover(false)}
          style={{
            padding: "7px 10px", borderRadius: 6, cursor: "pointer",
            background: hover ? "color-mix(in oklch, var(--danger) 13%, transparent)" : "transparent",
          }}
        >
          <Text style={{ fontSize: 12, color: "var(--danger)" }}>{deleteLabel}</Text>
        </Box>
      </Box>
    </>
  );
}

